#!/usr/bin/env python3
"""Join distinct exact-source finite slices; never upgrade a failed receipt."""
import pathlib,json,hashlib,importlib.util,sys,re
H=pathlib.Path(__file__).resolve().parent
sha=lambda p:hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
paths={'v4Large':H/'production-candidate-v4/evidence/large-1791365640480813099/receipt.json','v5Cleanup':H/'production-candidate-v5/evidence/cleanup-1791366078591710869/receipt.json','v5Overflow':H/'production-candidate-v5/evidence/large-1791366033230965729/receipt.json'}
r={k:json.loads(p.read_text()) for k,p in paths.items()}
assert r['v4Large']['status']=='FAIL'
assert r['v5Cleanup']['status']=='FINITE_DERIVED_NAT_REGISTERED_AFFINE_CLEANUP_PASS'
assert r['v5Overflow']['status']=='FINITE_OLD_OVERFLOW_MUTANT_ISOLATED_PASS'
for record in r.values():
 assert all(sha(p)==h for p,h in record['pins'].items()),'recorded input pin drift'
 for stage in record['stages'].values():
  base=pathlib.Path(stage['path']);actual={str(p.relative_to(base)):sha(p) for p in base.rglob('*.bend')};assert actual==stage['derivedInventory']
 for command in record['commands']:
  if 'log' in command:assert sha(command['log'])==command['sha256']
 for p,h in record.get('generatedPins',{}).items():assert sha(p)==h
def normalized_tools(record):
 tools=dict(record['tools']);tools['resolvedLibraries']={p:re.sub(r'\(0x[0-9a-fA-F]+\)', '(ASLR-address)', text) for p,text in tools['resolvedLibraries'].items()};return tools
assert normalized_tools(r['v4Large'])==normalized_tools(r['v5Cleanup'])==normalized_tools(r['v5Overflow'])
def normalized(stage):return {k.replace('production-candidate-v4','production-candidate-v5'):h for k,h in stage['normalInventory'].items()}
assert normalized(r['v4Large']['stages']['normal'])==normalized(r['v5Cleanup']['stages']['normal'])==normalized(r['v5Overflow']['stages']['normal'])
sys.path.insert(0,str(H/'production-candidate-v5'))
spec=importlib.util.spec_from_file_location('large_oracle',H/'production-candidate-v5/large-controls.py');oracle=importlib.util.module_from_spec(spec);spec.loader.exec_module(oracle)
observations=[];retrospective={}
for case in ['normal','graph-remove-wrong-order','graph-remove-drop-survivors']:
 stage=pathlib.Path(r['v4Large']['stages'][case]['path'])
 for backend in ['js','native']:
  program=stage/('world.js' if backend=='js' else 'world-native')
  argvSuffix=['node',str(program)] if backend=='js' else [str(program),'--threads','1','--gpu','off']
  matches=[c for c in r['v4Large']['commands'] if c['argv'][3:]==argvSuffix];assert len(matches)==1
  command=matches[0];assert command['exit']==0 and command['capSeconds']==5
  text=pathlib.Path(command['log']).read_text();witnesses=oracle.validate(text,case!='normal')
  if case!='normal':assert [w['checkpoint'] for w in witnesses]==[3,7] and all('all-graph-fields=false' in w['actual'] for w in witnesses)
  receiptResult=[x for x in r['v4Large']['results'] if x['case']==case and x['backend']==backend];assert len(receiptResult)==1 and receiptResult[0]['witnesses']==witnesses
  for p in [program,stage/'world.c' if backend=='native' else program]:retrospective[str(p)]=sha(p)
  observations.append({'case':case,'backend':backend,'originalReceipt':'v4Large','originalCommand':command,'fullRecordCount':6,'witnesses':witnesses})
assert {(x['case'],x['backend']) for x in r['v5Cleanup']['results']}=={(c,b) for c in r['v5Cleanup']['stages'] for b in ['js','native']}
assert r['v5Overflow']['selection']=='overflowing-old-bound only'
assert len(r['v5Overflow']['results'])==2 and all(x['notSemanticCompletion'] for x in r['v5Overflow']['results'])
output={'status':'REVIEWABLE_DISTINCT_SOURCE_BOUND_FINITE_SLICES','notOneFreshAllPassExecution':True,'receipts':{k:{'path':str(p),'sha256':sha(p),'originalStatus':r[k]['status']} for k,p in paths.items()},'normalBendInventoriesEqualAfterPathNormalization':True,'toolPinsAndEnvironmentEqual':True,'resolvedLibraryListsEqualIgnoringOnlyASLRAddresses':True,'v4LargeObservations':observations,'retrospectiveV4GeneratedCapture':{'explicitlyNotPinsRecordedInFailedReceipt':True,'reason':'generatedPins finalized only at runner success; actual runner guarded generated bytes in-memory before/after each operation','pins':retrospective},'v5CleanupFullRecordsPerBackend':36,'v5CleanupTenIntendedSpanNegatives':len(r['v5Cleanup']['negativeResults']),'v5CleanupCompilingMutantsPerBackend':6,'v5OverflowOnly':'actual old scalar arithmetic Nat48 fail-stop, not completion','recipeSHA256':sha(__file__),'proof':False,'productionAdoption':False,'performanceAcceptance':False}
out=H/'production-candidate-v5/evidence/aggregate-candidate.json';out.write_text(json.dumps(output,indent=2)+'\n');print(out)
